defense.vulnerable_config:
# AWS Security Group / firewall -- all inbound open
# No access control on management paths
resource "aws_security_group_rule" "allow_all" {
  type        = "ingress"
  from_port   = 0
  to_port     = 65535
  protocol    = "-1"
  cidr_blocks = ["0.0.0.0/0"]
}

# nginx -- no auth on /admin, /api, management paths
location /admin { proxy_pass http://backend; }
location /api   { proxy_pass http://backend; }

defense.secure_config:
# AWS Security Group -- restrict to known CIDR only
resource "aws_security_group_rule" "restrict_inbound" {
  type        = "ingress"
  from_port   = 443
  to_port     = 443
  protocol    = "tcp"
  cidr_blocks = ["10.0.0.0/8"]
}

# nginx -- auth + restrict management paths
location /admin {
  allow 10.0.0.0/8;
  deny  all;
  auth_basic "Admin Area";
  auth_basic_user_file /etc/nginx/.htpasswd;
  proxy_pass http://backend;
}
